args.sparql:
SELECT ?mother ?motherLabel WHERE { 
  <http://dbpedia.org/resource/Margaret_of_Valois,_Countess_of_Blois>  dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
} LIMIT 10

SELECT DISTINCT ?grandfather ?grandfatherLabel WHERE {
  <http://dbpedia.org/resource/Margaret,_Countess_of_Anjou> ?p ?grandfather .
  VALUES ?p { dbp:father dbo:parent dbp:parents dbp:parent }
  OPTIONAL { ?grandfather rdfs:label ?grandfatherLabel . FILTER(lang(?grandfatherLabel) = "en") }
}

SELECT DISTINCT ?maternalGrandfather ?maternalGrandfatherLabel WHERE {
  <http://dbpedia.org/resource/Margaret_of_Valois,_Countess_of_Blois> dbp:mother ?mother .
  ?mother ?p ?maternalGrandfather .
  VALUES ?p { dbp:father dbo:parent dbp:parents dbp:parent }
  OPTIONAL { ?maternalGrandfather rdfs:label ?maternalGrandfatherLabel . FILTER(lang(?maternalGrandfatherLabel) = "en") }
} LIMIT 10

SELECT DISTINCT ?maternalGrandfather ?maternalGrandfatherLabel WHERE {
  <http://dbpedia.org/resource/Margaret_of_Valois,_Countess_of_Blois> dbp:mother ?mother .
  ?mother ?p ?maternalGrandfather .
  VALUES ?p { dbp:father dbo:parent dbp:parents dbp:parent }
  OPTIONAL { ?maternalGrandfather rdfs:label ?maternalGrandfatherLabel . FILTER(lang(?maternalGrandfatherLabel) = "en") }
} LIMIT 10

output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?maternalGrandfather ?maternalGrandfatherLabel WHERE {
  <http://dbpedia.org/resource/Margaret_of_Valois,_Countess_of_Blois> dbp:mother ?mother .
  ?mother ?p ?maternalGrandfather .
  VALUES ?p {
    dbp:father dbo:parent dbp:parents dbp:parent
  }
  OPTIONAL {
    ?maternalGrandfather rdfs:label ?maternalGrandfatherLabel .
    FILTER(lang(?maternalGrandfatherLabel) = "en")
  }
}
LIMIT 10

